{
  "schema": {
    "title": "Review progress",
    "description": "Record how the plan is going. Tick \"The plan has been carried out\" to start the evaluation; otherwise the next check is in 14 days.",
    "type": "object",
    "required": [
      "ProgressReview"
    ],
    "properties": {
      "Plan": {
        "type": "object",
        "title": "Development plan",
        "properties": {
          "period": {
            "type": "string",
            "title": "Plan period"
          },
          "goals": {
            "type": "array",
            "title": "Goals",
            "items": {
              "type": "object",
              "title": "Goal",
              "properties": {
                "title": {
                  "type": "string",
                  "title": "Goal"
                },
                "type": {
                  "type": "string",
                  "title": "Type",
                  "enum": [
                    "SKILL",
                    "KNOWLEDGE",
                    "BEHAVIOUR",
                    "CAREER"
                  ],
                  "enumNames": [
                    "Skill",
                    "Knowledge",
                    "Behaviour",
                    "Career"
                  ]
                },
                "description": {
                  "type": "string",
                  "title": "Description"
                },
                "successCriteria": {
                  "type": "string",
                  "title": "How we know it is achieved"
                },
                "targetDate": {
                  "type": "string",
                  "title": "Target date",
                  "format": "date"
                }
              },
              "required": [
                "title",
                "type",
                "successCriteria",
                "targetDate"
              ]
            },
            "minItems": 1
          }
        },
        "required": [
          "period",
          "goals"
        ]
      },
      "Activities": {
        "type": "array",
        "title": "Activities in this round",
        "items": {
          "type": "object",
          "title": "Activity",
          "properties": {
            "type": {
              "type": "string",
              "title": "Type",
              "enum": [
                "PROJECT",
                "TRAINING",
                "COACHING"
              ],
              "enumNames": [
                "Project",
                "Training",
                "Coaching"
              ]
            },
            "description": {
              "type": "string",
              "title": "Description"
            },
            "relatedGoal": {
              "type": "string",
              "title": "Supports goal"
            },
            "dueDate": {
              "type": "string",
              "title": "Due date",
              "format": "date"
            },
            "status": {
              "type": "string",
              "title": "Status",
              "enum": [
                "PLANNED",
                "IN_PROGRESS",
                "DONE"
              ],
              "enumNames": [
                "Planned",
                "In progress",
                "Done"
              ]
            },
            "outcome": {
              "type": "string",
              "title": "Outcome"
            }
          }
        }
      },
      "ProgressReviews": {
        "type": "array",
        "title": "Progress reviews in this round",
        "items": {
          "type": "object",
          "title": "Review",
          "properties": {
            "date": {
              "type": "string",
              "title": "Review date",
              "format": "date"
            },
            "onTrack": {
              "type": "boolean",
              "title": "On track",
              "default": true
            },
            "notes": {
              "type": "string",
              "title": "Notes"
            },
            "adjustments": {
              "type": "string",
              "title": "Adjustments to the plan"
            },
            "planCompleted": {
              "type": "boolean",
              "title": "The plan has been carried out: start the evaluation",
              "default": false
            }
          }
        }
      },
      "ProgressReview": {
        "type": "object",
        "title": "Progress review",
        "properties": {
          "date": {
            "type": "string",
            "title": "Review date",
            "format": "date"
          },
          "onTrack": {
            "type": "boolean",
            "title": "On track",
            "default": true
          },
          "notes": {
            "type": "string",
            "title": "Notes"
          },
          "adjustments": {
            "type": "string",
            "title": "Adjustments to the plan"
          },
          "planCompleted": {
            "type": "boolean",
            "title": "The plan has been carried out: start the evaluation",
            "default": false
          }
        },
        "required": [
          "date",
          "onTrack",
          "planCompleted"
        ]
      }
    }
  },
  "uiSchema": {
    "Plan": {
      "ui:order": [
        "period",
        "goals"
      ],
      "goals": {
        "items": {
